<template>
    <TouchForm :fields="fields" :onFinish="onFinish" :skipSummary="true" @onIndex="nextField = ''"
        :activeField="nextField" />
</template>

<script setup lang="ts">
import Validation from "@/components/Forms/validations/StandardValidations"
import TouchForm from "@/components/Forms/TouchScreenForm.vue"
import { FieldType } from "@/components/Forms/BaseFormElements";
import { Field, Option } from "@/components/Forms/FieldInterface";
import { Client, ClientError } from "@/composables/client";
import { toastDanger, toastSuccess, toastWarning } from "@/utils/Alerts";
import { ref } from "vue";
import { isEmpty } from "lodash";
import router from "@/router";
import HisDate from "@/utils/Date"
import { EstimationFieldType, generateDateFields } from "@/helpers/form/MultifieldDateHelper"
import { groupByTag } from "@/utils/Form";

const client = Client()

const nextField = ref('')

const givenNameField = () => {
    return {
        id: 'first_name',
        helpText: 'First name',
        type: FieldType.TT_TEXT,
        computedValue: (val: Option) => ({
            person: { first_name: val.value }
        }),
        options: async (f: any) => {
            if (f.first_name?.value) {
                const res = await client.getJson('clients/search_by_name', {
                    first_name: f.first_name?.value
                })
                return res?.data.map((v: string) => ({ label: v, value: v }))
            }
            return []
        },
        validation: (val: any) => Validation.isName(val),
    }
}

const familyNameField = () => {
    return {
        id: 'last_name',
        helpText: "Last name",
        type: FieldType.TT_TEXT,
        computedValue: (val: Option) => ({
            person: { last_name: val.value }
        }),
        options: async (f: any) => {
            if (f.last_name?.value) {
                const res = await client.getJson('clients/search_by_name', {
                    last_name: f.last_name?.value
                })
                return res?.data.map((v: string) => ({ label: v, value: v }))
            }
            return []
        },
        validation: (val: any) => Validation.isName(val),
    }
}

const middleNameField = () => {
    return {
        id: 'middle_name',
        helpText: "Middle name(Optional)",
        type: FieldType.TT_TEXT,
        computedValue: (val: Option) => {
            if (!val) return
            return {
                person: { middle_name: val.value }
            }
        },
    }
}

const genderField = () => {
    return {
        id: 'sex',
        helpText: 'Gender',
        type: FieldType.TT_SELECT,
        computedValue: (val: Option) => ({
            person: { sex: val.value }
        }),
        validation: (val: Option) => Validation.required(val),
        options: () => ([
            {
                label: 'Female',
                value: 'F'
            },
            {
                label: 'Male',
                value: 'M'
            }
        ])
    }
}

const birthdateField = () => {
    const config = {
        id: 'date_of_birth',
        summaryLabel: 'Date of Birth',
        helpText: 'Birth',
        required: true,
        minDate: () => HisDate.estimateDateFromAge(100),
        maxDate: () => HisDate.sessionDate(),
        estimation: {
            allowUnknown: true,
            allowUnknownMonthDay: true,
            estimationFieldType: EstimationFieldType.AGE_ESTIMATE_FIELD,
        },
        computeValue: (date: string, isEstimate: boolean) => {
            return {
                person: {
                    date_of_birth: date,
                    birth_date_estimated: isEstimate
                }
            }
        }
    }
    return generateDateFields(config)
}

const physicalAddressField = () => {
    return {
        id: "physical_address",
        helpText: "Physical address",
        type: FieldType.TT_TEXT,
        computedValue: (val: Option) => ({
            client_identifiers: {
                physical_address: val.value
            }
        }),
        validation: (val: Option) => Validation.required(val)
    }
}

const externalPatientNumberField = () => {
    return {
        id: "npid",
        helpText: "External Patient Number (Option)",
        type: FieldType.TT_TEXT,
        computedValue: (val: Option) => {
            if (!val) return
            return {
                client_identifiers: {
                    npid: val?.value || ''
                }
            }
        }
    }
}

const searchResultsField = () => {
    return {
        id: 'results',
        helpText: 'Search results',
        type: FieldType.TT_PERSON_RESULT_VIEW,
        dynamicHelpText: (form: any) => {
            return `Search results for "${form.first_name.value} ${form.last_name.value} | ${form.sex.label}"`;
        },
        options: async (f: any) => {
            const payload = {
                'first_name': f.first_name.value,
                'last_name': f.last_name.value,
                'gender': f.sex.value
            }
            const res = await client.getJson('clients/search_dde', payload)
            if (!res?.ok) {
                toastWarning('Unable to find client')
                return []
            }
            return res.data.map((person: any, index: number) => {
                const isRemote = !person.client_id;
                return {
                    label: `${person.first_name} ${person.last_name} (${person.date_of_birth})`,
                    value: isRemote ? index : person.client_id,
                    isRemote,
                    other: {
                        person,
                        options: [
                            { label: "First name", value: person.first_name },
                            { label: "Middle name", value: person.middle_name },
                            { label: "Last name", value: person.last_name },
                            { label: "Sex", value: person.sex },
                            { label: "Birthdate", value: person.date_of_birth },
                            { label: "Is birth estimated?", value: person.birth_date_estimated ? 'Yes' : 'No' },
                            { label: "Source", value: isRemote ? 'Remote (DDE)' : 'Local' }
                        ]
                    },
                }
            })
        },
        config: {
            hiddenFooterBtns: [
                'Clear',
                'Next',
                'Back',
                'Finish'
            ],
            footerBtns: [
                {
                    name: 'Edit Search',
                    slot: 'end',
                    onClick: () => {
                        nextField.value = 'first_name'
                    }

                },
                {
                    name: 'New Client',
                    slot: 'end',
                    onClick: () => {
                        nextField.value = '_NEXT_FIELD_'
                    }
                },
                {
                    name: 'New Order',
                    color: 'success',
                    slot: 'end',
                    state: {
                        disabled: {
                            default: () => true,
                            onValue(_: any, form: any) {
                                return isEmpty(form.results)
                            }
                        }
                    },
                    onClick: async (form: any) => {
                        const selectedResult = form.results;
                        if (selectedResult.other.person.source === 'remote') {
                            try {
                                const response = await registerRemotePerson(selectedResult.other.person);
                                if (response?.data?.client_id) {
                                    return router.push(`/order/${response.data.client_id}`);
                                } else {
                                    console.log('Failed to register remote client');
                                }
                            } catch (error) {
                                console.error('Error registering remote person:', error);
                            }
                            return;
                        }
                        // For local clients
                        return router.push(`/order/${selectedResult.value}`);
                    }
                }
            ]
        }
    }
}

const fields: Field[] = [
    givenNameField(),
    middleNameField(),
    familyNameField(),
    genderField(),
    searchResultsField(),
    ...birthdateField(),
    physicalAddressField(),
    externalPatientNumberField()
]

interface ClientResponse {
    ok: boolean;
    data?: {
        client_id: string;
    };
    error?: string;
}

const registerRemotePerson = async (person: any): Promise<ClientResponse> => {
    try {
        const response = await client.postJson('clients', {
            client: { id: '', uuid: person.uuid },
            person: {
                first_name: person.first_name,
                middle_name: person.middle_name,
                last_name: person.last_name,
                sex: person.sex,
                date_of_birth: person.date_of_birth,
                birth_date_estimated: person.birth_date_estimated || false
            },
            client_identifiers: {
                npid: person.npid || '',
                current_district: person.current_district || '',
                current_traditional_authority: person.current_traditional_authority || '',
                current_village: person.current_village || '',
                home_village: person.home_village || '',
                home_district: person.home_district || '',
                home_traditional_authority: person.home_traditional_authority || '',
            }
        }) as ClientResponse;

        if (response?.ok) {
            return response;
        } else {
            const errorMsg = response?.error || 'Failed to register client';
            return { ok: false, error: errorMsg };
        }
    } catch (error) {
        console.error('Error registering remote person:', error);
        const errorMsg = 'An error occurred while registering the client';
        return { ok: false, error: errorMsg };
    }
};

const onFinish = (_: any, payload: any) => {
    client.postJson('clients', {
        client: { id: '', uuid: '' },
        ...groupByTag(payload, 'person'),
        ...groupByTag(payload, 'client_identifiers')
    }).then(res => {
        if (res?.ok) {
            router.push(`/order/${res.data.client_id}`)
            return toastSuccess('Client created')
        }
        toastWarning(res?.error || 'Unable to create')
    }).catch(() => toastDanger(ClientError.GENERAL_ERROR))
}

</script>
